// TH15 synthetic alias copied from transcribe/th15/touhou-bullets.ecl.
// type 4 = TH15_BALL, base radius 4, colors 0..15.
const TH15_BALL: int = 416;

// TH15 v1.00b Extra Stage 7 道中 第1波（th15_s7_w01）
// 源：st07.ecl.txt:1118-1132 MainSub00；依赖 GirlA01 93-102 / GirlA01_at 104-119 /
//     GirlA01_at2 121-141。卡帧0 = MainSub00 入口。
// 源排程：wait(120)，随后 25 轮，每轮左侧敌人、wait20、右侧镜像敌人、wait20。

const TIME_LIMIT: int = 1824;   // 120 开场 + 1700 源窗口估计 + 4 启动余量（任务单）
const OPENING_WAIT: int = 120;  // 源 MainSub00 的 wait(120)
const GIRL_COLOR: int = 6;      // 源 GirlA01_at2: etSprite(0, 4, 6)

// 源 GirlA01_at2：wait(10) 后共 10 发单路单层自机狙，速度 4.2。
// 保留出生 ANIM 的 4×速度退位移：出生点沿弹角后退 4*4.2=16.8px。
async sub girl_fire() {
    wait(10);
    for i in 0..10 {
        var aim: angle = aim_player();
        var back: fx = 4fx * 4.2fx;
        _ = fire(TH15_BALL, GIRL_COLOR,
                 $self_x - back * cos(aim), $self_y - back * sin(aim),
                 4.2fx, aim, none, none);
        wait(1 + rand(20));      // 源 wait(1 + ($RAND % 20))
    }
}

// 源 GirlA01_at：框 → async 发弹 → 两段 moveVelTime → 无限 wait(1000) 循环。
// 右侧由 enmCreateM 创建（子镜像=1），移动角在指令写入点按 x 轴镜像：
// 22.5°→157.5°、90°→90°、-168.75°(=191.25°)→348.75°。
async sub girl(mirror: int) {
    set_invuln(65535);
    set_hurtbox(12fx);   // 源 setHurtbox(24,24)：普通圆半径 = 24/2
    set_hitbox(8fx);     // 源 setHitbox(16,16)：16/2
    spawn girl_fire();
    if mirror == 0 {
        move_vel(0, 4096bam, 3.2fx, EASE_LINEAR);      // 源 moveVel(0.3926991rad=22.5°, 3.2)
        move_vel(120, 16384bam, 2.0fx, EASE_QUAD_IN);  // 源 moveVelTime(120, mode1=t², 90°, 2.0)
    } else {
        move_vel(0, 28672bam, 3.2fx, EASE_LINEAR);     // 镜像 157.5°
        move_vel(120, 16384bam, 2.0fx, EASE_QUAD_IN);
    }
    wait(120);
    if mirror == 0 {
        move_vel(60, 34800bam, 4.0fx, EASE_QUAD_OUT);  // 源 moveVelTime(60, mode4, -168.75°, 4.0)
    } else {
        move_vel(60, 63488bam, 4.0fx, EASE_QUAD_OUT);  // 镜像 348.75°
    }
    loop { wait(1000); }   // 源 GirlA01_at_248: wait(1000) 无限循环
}

// 源 MainSub00：25 轮，左 enmCreate / 右 enmCreateM，各带 %RANDF2*8 的 x 抖动。
// 父为 (0,0)，故相对坐标即世界坐标；右侧 +150 由创建参数给出，镜像只作用于其移动。
async sub wave() {
    wait(OPENING_WAIT);
    for k in 0..25 {
        var dxl: fx = (rand(4096) as fx) / 256 - 8fx;  // 源 %RANDF2*8 ∈ [-8,8)
        _ = spawn_enemy(-150fx + dxl, -16fx, 50, 1, 1000, 0, girl(0));
        wait(20);
        var dxr: fx = (rand(4096) as fx) / 256 - 8fx;
        _ = spawn_enemy(150fx + dxr, -16fx, 50, 1, 1000, 0, girl(1));
        wait(20);
    }
}

// 独立无敌外壳：control 只承载段事件并关闭体碰。
async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
